(()=>{let context,current,ticket=0;const decoded=new Map(),pending=new Map();const manifest=window.BALLOON_VOICES||{};function engine(){context??=new(window.AudioContext||window.webkitAudioContext)();return context}function stop(){ticket++;if(current){try{current.stop()}catch{}current=null}}async function load(lang){if(decoded.has(lang))return decoded.get(lang);if(pending.has(lang))return pending.get(lang);const entry=manifest[lang];if(!entry)return null;const bytes=window.balloonDesktop?.readVoice?window.balloonDesktop.readVoice(lang).then(b=>b.buffer.slice(b.byteOffset,b.byteOffset+b.byteLength)):fetch(new URL(entry.file,document.baseURI)).then(r=>{if(!r.ok)throw Error('Voice download failed');return r.arrayBuffer()});const task=bytes.then(b=>engine().decodeAudioData(b)).then(buffer=>{if(decoded.size>=3)decoded.delete(decoded.keys().next().value);decoded.set(lang,buffer);return buffer}).finally(()=>pending.delete(lang));pending.set(lang,task);return task}async function play(value,lang){stop();const mine=ticket;const key=/^[a-z]$/i.test(value)?value.toUpperCase():String(value);const entry=manifest[lang],cue=entry?.cues[key];if(!cue)return false;try{const ctx=engine();await ctx.resume();const buffer=await load(lang);if(ticket!==mine||!buffer)return false;const source=ctx.createBufferSource(),gain=ctx.createGain();source.buffer=buffer;gain.gain.value=.8;source.connect(gain).connect(ctx.destination);current=source;source.start(0,cue[0],cue[1]);return true}catch{return false}}function unlock(){try{engine().resume().catch(()=>{})}catch{}}document.addEventListener('pointerup',unlock,{capture:true,passive:true});document.addEventListener('click',unlock,{capture:true,passive:true});document.addEventListener('visibilitychange',()=>{if(document.hidden)stop()});window.balloonVoice={play,stop,load};})();
